  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const lines = [...votes].sort((a, b) =>
      a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0,
    ).map(([c, v]) => [c, v.toString()])
    const round = { lines, exhausted: (total - active).toString(), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) {
      if (v * 2n > active) return { rounds, winner: c }
    }
    let pool = [...continuing]
    for (let r = 0; r < rounds.length && pool.length > 1; r++) {
      let min = null
      for (const c of pool) {
        const v = history.get(c)[r]
        if (min === null || v < min) min = v
      }
      pool = pool.filter((c) => history.get(c)[r] === min)
    }
    pool.sort()
    const out = pool[pool.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
}
"}

